import {modelQuoteForSeat, modelQuoteHTML, candidateQuoteHTML} from './model-quotes.js';
import {candidateEvidence,eligiblePortrait,coverageAudit,rosterEvidence,portraitStatus} from './profile-evidence.js';
import {verifiedProbability} from './election-visual.js';
const partyNames={D:'民主党',R:'共和党',I:'独立',L:'自由意志党',G:'绿党'};
const placeholder='<svg viewBox="0 0 80 90" aria-hidden="true"><circle cx="40" cy="28" r="13"/><path d="M16 78v-9c0-28 48-28 48 0v9"/></svg><small>非真人占位图</small>';
const link=(url,text,esc)=>url?`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(text)} ↗</a>`:'';
const items=(list,esc)=>(list||[]).map(x=>`<li>${esc(x.text||x.title||x)} ${link(x.source,'来源',esc)}</li>`).join('');
const record=(title,list,esc)=>`<section class="profile-evidence-block"><h4>${esc(title)}</h4>${list?.length?`<ul>${items(list,esc)}</ul>${list.some(x=>x.attribution)?`<details class="source-details"><summary>来源与归因</summary><ul>${list.filter(x=>x.attribution).map(x=>`<li>${esc(x.attribution)} · ${link(x.source,'来源',esc)}</li>`).join('')}</ul></details>`:''}`:'<p class="missing-evidence">尚未收录</p>'}</section>`;
function portrait(person,esc){const photo=eligiblePortrait(person),original=person?.photo||person?.portrait;return `<div class="portrait-record"><div class="profile-image">${photo?`<img src="${esc(photo.url)}" alt="${esc(person.name)}" loading="lazy" referrerpolicy="no-referrer">`:placeholder}</div><details class="portrait-credit"><summary>照片来源</summary><p class="photo-status">${esc(portraitStatus(person))}</p>${original?`${esc(original.credit||original.attribution||original.license||'')} · ${link(original.source,'图片来源',esc)} · ${link(original.rightsSource,'使用依据',esc)}${original.photoDateNote?`<p>${esc(original.photoDateNote)}</p>`:''}`:''}</details></div>`;}
export function profileHTML(seat,profile,esc,label,evidence={}){
 const p=profile||{},inc=p.incumbent||{},probability=verifiedProbability(seat),roster=rosterEvidence(p),quote=modelQuoteForSeat(seat,p,evidence);
 const current=`<section class="incumbent-record"><p class="eyebrow">CURRENT OFFICEHOLDER</p><div class="candidate-heading"><div>${portrait({...inc,name:inc.name||seat.incumbent},esc)}</div><div><h2>${esc(inc.name||seat.incumbent||'现任空缺')}</h2><span class="profile-badge">现任 · ${esc(partyNames[seat.currentParty]||'空缺')}</span><p>${esc(inc.role||'')}</p></div></div><p>${esc(inc.background||'履历待核验')}</p>${link(inc.backgroundSource||inc.source||seat.source,'现任资料来源',esc)}${record('政策主张',inc.policyPositions?.length?inc.policyPositions:inc.positions,esc)}${record('成果与立法工作',inc.majorAchievements?.length?inc.majorAchievements:inc.achievements||inc.accomplishments,esc)}${record('荣誉记录',inc.honors,esc)}</section>`;
 const candidates=(p.candidates||[]).map(c=>{const e=candidateEvidence(c);return `<article class="candidate-card party-${esc(c.party)}"><p class="eyebrow">${c.isWriteIn===true?'写入候选记录':'2026 CANDIDATE RECORD'}</p><div class="candidate-heading"><div>${portrait(c,esc)}</div><div><h3>${esc(c.name)}</h3><span class="profile-badge">${esc(partyNames[c.party]||c.party||'党籍待核验')}</span><p class="candidate-stage">${c.electionStage==='2026-11-03-open-primary'?'2026年11月3日开放式初选':c.generalContestStatus==='unopposed-no-printed-contest'?'大选无对手；依法不印在选票上':c.isWriteIn===true?'写入候选记录':c.printedOnBallot===true?'印刷选票候选记录':''}</p></div></div>${candidateQuoteHTML(quote,c,esc)}<p>${link(e.source,'参选依据',esc)} · 资料时间 ${esc(c.asOf||c.verifiedAt||p.profileAsOf||'待核验')}</p>${e.biography?`<p>${esc(c.background)}</p>${link(e.biographySource,'履历依据',esc)}`:'<p class="missing-evidence">尚未收录</p>'}${record('政策主张',e.policy,esc)}${record('成果与立法工作',e.achievements,esc)}${record('荣誉记录',e.honors,esc)}<details class="source-details"><summary>资料状态</summary><p class="gap-list">待补证据：${e.gaps.length?e.gaps.map(esc).join(' · '):'已记录各类来源；仍需持续复核'}</p></details>${(c.polls||[]).map(q=>`<div class="candidate-poll"><strong>${q.share==null?'—':esc(q.share)+'%'}</strong><div>${esc(q.pollster)} · 原始民调<br>${esc(q.fieldStart)}—${esc(q.fieldEnd)} · ${esc(q.sampleType||'样本见来源')}<br>${link(q.source,'调查原文',esc)}</div></div><details class="poll-method"><summary>调查方法与限制</summary><p>${esc(q.note||'')}</p><p>样本：${esc(q.sample||'见来源')}；模式：${esc(q.mode||'见来源')}；权重：${esc(q.weighting||'见来源')}；误差：${q.moe==null?'见来源':'±'+esc(q.moe)+'个百分点'}</p></details>`).join('')}</article>`;}).join('');
 return `<p class="eyebrow">${esc(label(seat))} / ${seat.contested2026?'2026竞选席位':'不改选席位'}</p>${modelQuoteHTML(quote,esc)}${current}${seat.contested2026?`<div class="divider"></div><h2>2026 候选记录</h2><details class="source-details"><summary>名单来源</summary><p>${roster.verified?'官方名单已核对；未单列的写入候选人仍可能未覆盖。':'名单尚未证明完整；其他党派、独立或写入候选人可能未覆盖。'} ${link(roster.source,'参选依据',esc)}</p></details>${candidates||'<p class="missing-evidence">此席暂无可展示的已核验候选记录。</p>'}${p.writeInCandidates?.length?`<section class="write-in-records"><h3>写入候选记录</h3><p>另列记录非穷尽，资格状态以各自来源为准。</p><ul>${p.writeInCandidates.map(c=>`<li><strong>${esc(c.name)}</strong> · ${esc(c.party||'')} ${link(c.source,'参选依据',esc)}</li>`).join('')}</ul></section>`:''}<details class="forecast-note"><summary>预测来源</summary>${probability?`<strong>来源模型胜选概率</strong><p>${Object.entries(probability.values).filter(([,v])=>v>0).map(([side,v])=>esc(partyNames[side]||side)+' '+esc(Math.round(v*1000)/10)+'%').join(' · ')}</p><p>${esc(probability.model)} · ${esc(probability.asOf)} · ${link(probability.source,'模型来源',esc)}</p>`:quote?`<a href="${esc(quote.source)}" target="_blank" rel="noopener">${esc(quote.model)} ↗</a>`:'<strong>尚未收录来源模型胜率。</strong>'}</details>`:''}<details class="source-details"><summary>资料来源与时间</summary><p class="small muted">资料截至 ${esc(p.profileAsOf||'待核验')}<br>${esc(p.note||'')}</p></details>`;
}
export function coverageHTML(seats,profiles,chamber,esc){const a=coverageAudit(seats,profiles,chamber);return `<div class="coverage-heading"><div><span class="eyebrow">CANDIDATES & EVIDENCE</span><h3>候选资料覆盖审计</h3></div><button id="download-profile-audit">下载缺失清单</button></div><div class="coverage-grid"><div><b>${a.seatsWithCandidates} / ${a.contestedSeats}</b><span>改选席已有候选记录</span></div><div><b>${a.candidateRecords}</b><span>候选人记录数</span></div><div><b>${a.completeRosters} / ${a.contestedSeats}</b><span>官方名单已核对</span></div><div><b>${a.portraits} / ${a.candidateRecords}</b><span>身份与使用依据齐备头像</span></div></div><details class="source-details"><summary>覆盖详情</summary><p class="small">写入候选记录 ${a.writeInRecords} · 另列记录非穷尽，资格状态以各自来源为准。</p><p class="small">已附来源：履历 ${a.biographies} · 政策 ${a.policies} · 成果 ${a.achievements} · 荣誉 ${a.honors}</p></details>`;}
export function installImageFallbacks(panel){for(const image of panel.querySelectorAll('.profile-image img'))image.onerror=()=>{const record=image.closest('.portrait-record');image.parentElement.innerHTML=placeholder;if(record)record.querySelector('.photo-status').textContent='源图加载失败';};}
